const test=require('node:test'),assert=require('node:assert/strict');
const e=require('../procedural-engine.js');
test('terrain settings are deterministic, finite and retain the biome',()=>{for(const spacing of [5,2.5,1.25]){const a=e.landscape(41,{spacing}),b=e.landscape(41,{spacing});assert.deepEqual(a,b);assert.equal(a.biome,'meadow-woodland-brook');assert.equal(a.terrain.grid.rows,180/spacing+1);assert(a.terrain.grid.heights.flat().every(Number.isFinite));}});
test('each landform control changes elevation without changing the seed',()=>{const a=e.landscape(41);for(const key of ['relief','hillHeight','hillScale','ridgeAngle','valleyWidth','flatGround','roughness','streamWidth','streamDepth','streamBends','streamPosition']){const b=e.landscape(41,{[key]:e.settings[key][2]});assert.notDeepEqual(b.terrain.grid.heights,a.terrain.grid.heights,key);assert.equal(b.seed,41);}});
test('vegetation respects brook banks and requested setbacks',()=>{for(const streamWidth of [2,12]){const w=e.landscape(41,{streamWidth,setback:18});for(const t of w.vegetation)assert(Math.abs(t.position[1]-e.brookY(w,t.position[0]))>=streamWidth/2+18+t.radius-.03);}assert.equal(e.landscape(41,{woodland:0}).vegetation.length,0);});
test('ranches use the edited terrain and work at every sampling resolution',()=>{for(const spacing of [5,2.5,1.25])for(const seed of [41,81,127]){const land=e.landscape(seed,{spacing,streamWidth:9}),g=e.grow(land);assert(g.checks.dry&&g.checks.nonoverlap&&g.checks.connected);for(const b of g.buildings){const [x,y]=b.polygon[0];assert.equal(b.baseZ,e.sample(g,x,y));}assert.equal(land.buildings.length,0);}});
test('bounds are validated and excessive terrain can reject a ranch cleanly',()=>{const c=e.normalize({relief:Infinity,streamWidth:-2,woodland:900});assert.equal(c.relief,e.defaults.relief);assert.equal(c.streamWidth,2);assert.equal(c.woodland,100);const w=e.landscape(41,{relief:14,hillHeight:8,valleyWidth:12,streamPosition:65});try{const g=e.grow(w);assert(g.checks.dry&&g.checks.nonoverlap&&g.checks.connected);}catch(err){assert.match(err.message,/No suitable|path could not reach/);}});
